import sys; sys.path.insert(0,'/home/claude/pcb/gen')
from schgen import Sheet
# PULSE-IN v1.0 : 1-channel pulse input adapter for PWR-CTRL J8 (-> D2) / J9 (-> D3)
S=Sheet('pulsein','OpenCruise PULSE-IN adapter (1 ch)',paper='A4')
R0603='Resistor_SMD:R_0603_1608Metric'; C0603='Capacitor_SMD:C_0603_1608Metric'
XH='Connector_JST:JST_XH_B4B-XH-A_1x04_P2.50mm_Vertical'
S.box(10,10,285,165,'PULSE-IN: vehicle speed / tach / sensor pulse (0-16 V, open collector) -> 3.3 V logic for XIAO D2/D3')
# connectors (bought separately, same as main board J8/J9)
S.part('J1','Connector_Generic','Conn_01x04',260,70,{'1':'+12V','2':'+5V','3':'GND','4':'OUT'},value='to PWR-CTRL J8/J9 (XH4)',fp=XH,lcsc='C144395')
S.part('J2','Connector_Generic','Conn_01x04',25,70,{'1':'SIG_IN','2':'GND','3':'+5V','4':'+12V'},value='PULSE IN (XH4)',fp=XH,lcsc='C144395')
# pull-up for open collector sources (JP1: 1-2 = 5 V, 2-3 = 12 V, open = none)
S.part('JP1','Jumper','SolderJumper_3_Open',60,40,{'1':'+5V','2':'PU','3':'+12V'},value='PULL-UP 5V|12V',fp='Jumper:SolderJumper-3_P1.3mm_Open_RoundedPad1.0x1.5mm')
S.part('R1','Device','R',60,60,{'1':'PU','2':'SIG_IN'},value='4.7k',fp=R0603,lcsc='C23162')
# front end
S.part('R2','Device','R',90,75,{'1':'SIG_IN','2':'SIG_A'},value='22k',fp=R0603,lcsc='C31850')
S.part('C1','Device','C',110,95,{'1':'SIG_A','2':'GND'},value='1nF',fp=C0603,lcsc='C1588')
S.part('DZ1','Device','D_Zener',125,95,{'1':'SIG_A','2':'GND'},value='BZT52C4V7',fp='Diode_SMD:D_SOD-123',lcsc='C173408')
S.part('R3','Device','R',140,95,{'1':'SIG_A','2':'TH'},value='10k',fp=R0603,lcsc='C25804')
S.part('JP2','Jumper','SolderJumper_2_Open',140,115,{'1':'TH','2':'GND'},value='12V THRESH',fp='Jumper:SolderJumper-2_P1.3mm_Open_RoundedPad1.0x1.5mm')
S.part('U1','74xGxx','74LVC1G17',170,75,{'2':'SIG_A','3':'GND','4':'PY','5':'+3V3'},value='74LVC1G17',fp='Package_TO_SOT_SMD:SOT-23-5',lcsc='C151394')
S.part('C4','Device','C',170,105,{'1':'+3V3','2':'GND'},value='100nF',fp=C0603,lcsc='C14663')
S.part('R4','Device','R',210,75,{'1':'PY','2':'OUT'},value='100',fp=R0603,lcsc='C22775')
S.part('R5','Device','R',200,100,{'1':'PY','2':'LED_A'},value='1k',fp=R0603,lcsc='C21190')
S.part('D1','Device','LED',215,115,{'1':'GND','2':'LED_A'},value='LED PULSE (red)',fp='LED_SMD:LED_0603_1608Metric',lcsc='C2286')
# 3.3 V for U1 (from 5V_EXT)
S.part('U2','Regulator_Linear','XC6206PxxxMR',100,140,{'1':'GND','2':'+3V3','3':'+5V'},value='XC6206P332MR',fp='Package_TO_SOT_SMD:SOT-23',lcsc='C5446')
S.part('C2','Device','C',75,145,{'1':'+5V','2':'GND'},value='1uF',fp=C0603,lcsc='C15849')
S.part('C3','Device','C',125,145,{'1':'+3V3','2':'GND'},value='1uF',fp=C0603,lcsc='C15849')
S.part('H1','Mechanical','MountingHole',250,140,{},value='M3',fp='MountingHole:MountingHole_3.2mm_M3',inbom=False)
S.flag('+5V',40,125); S.flag('+12V',50,125); S.flag('GND',60,125)
S.note('Input: 0-16 V push-pull, or open collector with JP1 pull-up. R2 22k + C1 1nF (tau 22 us, up to ~10 kHz), DZ1 clamps U1 input < 5 V.\nU1 Schmitt @3.3 V: VT+ 1.8 V / VT- 1.0 V. JP2 closed (12 V signals only): threshold ~5.8 V / 3.2 V for noisy 12 V lines.\nDo NOT close JP2 with 5 V or 3.3 V signals. LED D1 blinks with the pulses. +5V / +12V on J2 power a sensor (PTC on main board).\nJ1 pin order = PWR-CTRL J8/J9 (1 VSW_EXT, 2 5V_EXT, 3 GND, 4 IO): use a straight XH4 cable.',15,155)
S.write('/home/claude/pcb/pulsein/pulsein.kicad_sch')
print(len(S.parts),'parts')
